import{_ as s,a0 as l,w as a,s as u,ao as d,I as r,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux有问必答：如何找出Linux中内置模块的信息 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何找出Linux中内置模块的信息 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何找出Linux中内置模块的信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何找出Linux中内置模块的信息 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 Linux FAQs with Answers--How to find information about built-in kernel modules on Linux","title":"Linux有问必答：如何找出Linux中内置模块的信息","tag":"201511","desc":""},"relativePath":"201511/20151012 Linux FAQs with Answers--How to find information about built-in kernel modules on Linux.md","filePath":"[post].md"}'),p={name:"201511/20151012 Linux FAQs with Answers--How to find information about built-in kernel modules on Linux.md"};function m(f,t,x,c,L,b){const o=l("Link");return a(),u("div",null,[t[13]||(t[13]=d(`<h1 id="linux有问必答-如何找出linux中内置模块的信息" tabindex="-1">Linux有问必答：如何找出Linux中内置模块的信息 <a class="header-anchor" href="#linux有问必答-如何找出linux中内置模块的信息" aria-label="Permalink to “Linux有问必答：如何找出Linux中内置模块的信息”">​</a></h1><blockquote><p><strong>提问</strong>：我想要知道Linux系统中内核内置的模块，以及每个模块有哪些参数。有什么方法可以得到内置模块和设备驱动的列表，以及它们的详细信息呢？</p></blockquote><p>现代Linux内核正在随着时间变化而迅速增长，以支持大量的硬件、文件系统和网络功能。在此期间，“可加载模块（loadable kernel modules，[LKM]）”的引入防止内核变得越来越臃肿，以及在不同的环境中灵活地扩展功能及硬件支持，而不必重新构建内核。</p><p>最新的Linux发行版的内核只带了相对较小的“内置模块（built-in modules）”，其余的特定硬件驱动或者自定义功能作为“可加载模块”来让你选择地加载或卸载。</p><p>内置模块被静态地编译进了内核。不像可加载内核模块可以动态地使用<code>modprobe</code>、<code>insmod</code>、<code>rmmod</code>、<code>modinfo</code>或者<code>lsmod</code>等命令地加载、卸载、查询模块，内置的模块总是在启动时就加载进了内核，不会被这些命令管理。</p><h3 id="找出内置模块列表" tabindex="-1">找出内置模块列表 <a class="header-anchor" href="#找出内置模块列表" aria-label="Permalink to “找出内置模块列表”">​</a></h3><p>要得到内置模块列表，运行下面的命令。</p><pre><code>$ cat /lib/modules/$(uname -r)/modules.builtin 
</code></pre><p><img src="https://farm1.staticflickr.com/697/21481933835_ef6b9c71e1_c.jpg" alt=""></p><p>你也可以用下面的命令来查看有哪些内置模块：</p><p><img src="https://farm6.staticflickr.com/5643/21295025949_57f5849c36_c.jpg" alt=""></p><h3 id="找出内置模块参数" tabindex="-1">找出内置模块参数 <a class="header-anchor" href="#找出内置模块参数" aria-label="Permalink to “找出内置模块参数”">​</a></h3><p>每个内核模块无论是内置的还是可加载的都有一系列的参数。对于可加载模块，<code>modinfo</code>命令可以显示它们的参数信息。然而这个命令对内置模块没有用。你会得到下面的错误。</p><pre><code>modinfo: ERROR: Module XXXXXX not found.
</code></pre><p>如果你想要查看内置模块的参数，以及它们的值，你可以在 <strong>/sys/module</strong> 下检查它们的内容。</p><p>在 /sys/module目录下，你可以找到内核模块（包含内置和可加载的）命名的子目录。进入每个模块目录，这里有个“parameters”目录，列出了这个模块所有的参数。</p><p>比如你要找出tcp_cubic（内核默认的TCP实现）模块的参数。你可以这么做：</p><pre><code>$ ls /sys/module/tcp_cubic/parameters 
</code></pre><p>接着阅读这个文件查看每个参数的值。</p><pre><code>$ cat /sys/module/tcp_cubic/parameters/tcp_friendliness 
</code></pre><p><img src="https://farm6.staticflickr.com/5639/21293886250_a199b9c8f7_c.jpg" alt=""></p><hr>`,22)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://ask.xmodulo.com/find-information-builtin-kernel-modules-linux.html"},{default:i(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/find-information-builtin-kernel-modules-linux.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),n(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:i(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const g=s(p,[["render",m]]);export{T as __pageData,g as default};
